/**
 * UI helper functions for duplicate receipt detection
 *
 * Specifications implemented:
 * - #{#dup1a} Visual duplicate highlighting
 * - #{#dup2a} Duplicate count display
 */

export interface DuplicateInfo {
	isDuplicate: boolean;
	count: number;
}

/**
 * Check if a receipt ID is part of any duplicate group
 *
 * @param receiptId - The receipt ID to check
 * @param duplicateGroups - Map of duplicate groups from detectDuplicates()
 * @returns true if receipt is in a duplicate group, false otherwise
 */
export function isDuplicate(receiptId: string, duplicateGroups: Map<string, string[]>): boolean {
	for (const ids of duplicateGroups.values()) {
		if (ids.includes(receiptId)) {
			return true;
		}
	}
	return false;
}

/**
 * Get duplicate information for a specific receipt
 *
 * @param receiptId - The receipt ID to check
 * @param duplicateGroups - Map of duplicate groups from detectDuplicates()
 * @returns Object with isDuplicate flag and count of receipts in the group
 */
export function getDuplicateInfo(
	receiptId: string,
	duplicateGroups: Map<string, string[]>
): DuplicateInfo {
	for (const ids of duplicateGroups.values()) {
		if (ids.includes(receiptId)) {
			return {
				isDuplicate: true,
				count: ids.length
			};
		}
	}
	return {
		isDuplicate: false,
		count: 0
	};
}

