async function createManual(e: Event): Promise<void> {
	e.preventDefault();

	manualError = null;

	const validation = validateManualReceipt(manual);
	if (!validation.ok) {
		manualError = { field: validation.field, message: validation.message };
		return;
	}

	try {
		const created = await receiptService.createManual(validation.value);
		allReceipts = [created, ...allReceipts];
		// Reset for the next entry — date defaults back to today; form stays expanded.
		manual = newManualReceiptForm();
		successMessage = `Receipt created: ${validation.value.merchant_name}`;
		setTimeout(() => {
			successMessage = null;
		}, 3000);
	} catch (err: unknown) {
		manualError = {
			field: 'form',
			message: err instanceof Error ? err.message : 'Failed to create receipt'
		};
	}
}

function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
	// #{#dup5a} Pre-compute duplicate IDs when filter is active
	let dupeIds: Set<string> | null = null;
	if (filterDuplicates) {
		const dupes = detectDuplicates(rcts);
		// eslint-disable-next-line svelte/prefer-svelte-reactivity -- local, non-reactive lookup set built and read within this call; SvelteSet would be inappropriate here
		dupeIds = new Set<string>();
		for (const ids of dupes.values()) {
			for (const id of ids) dupeIds.add(id);
		}
	}

	return rcts.filter((r) => {
		// #{#dtv3a} Filter by suspicious_date (Needs Review)
		if (filterNeedsReview && !r.suspicious_date) return false;

		// #{#dup5a} Filter by duplicate status
		if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;

		// #{#sdf1b} Filter by date range using URL parameters
		if (!matchesDateRange(r.transaction_date, urlDateFrom, urlDateTo)) return false;

		// Filter by merchant name (local state)
		if (filterMerchant) {
			const merchantSearch = filterMerchant.toLowerCase();
			const merchant = (r.merchant_name || '').toLowerCase();
			if (!merchant.includes(merchantSearch)) return false;
		}

		// Filter by amount range (local state)
		if (filterAmountMin && r.total_amount !== null) {
			const minAmount = parseFloat(filterAmountMin);
			if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
		}
		if (filterAmountMax && r.total_amount !== null) {
			const maxAmount = parseFloat(filterAmountMax);
			if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
		}

		return true;
	});
}

function applyFilterValues(): void {
	// #{#sdf2a} Update URL with date filters
	const params = applyDateFilterParams(
		$page.url.searchParams,
		tempFilterDateFrom,
		tempFilterDateTo
	);
	goto(resolve(`/receipts?${params.toString()}`), { replaceState: true, keepFocus: true });

	// Apply non-date filters locally
	filterMerchant = tempFilterMerchant;
	filterAmountMin = tempFilterAmountMin;
	filterAmountMax = tempFilterAmountMax;
}

function clearClientFilters(): void {
	// #{#sdf2a} Clear URL date filters
	const params = clearDateFilterParams($page.url.searchParams);
	goto(resolve(`/receipts?${params.toString()}`), { replaceState: true, keepFocus: true });

	// Clear local filters
	tempFilterMerchant = '';
	tempFilterAmountMin = '';
	tempFilterAmountMax = '';
	filterMerchant = '';
	filterAmountMin = '';
	filterAmountMax = '';

	// #{#dtv3a} Clear Needs Review filter
	filterNeedsReview = false;

	// #{#dup5a} Clear Duplicates filter
	filterDuplicates = false;
}

// applyClientFilters reads every filter variable (URL date range + local filters),
// so $derived tracks them all — no explicit dependency list needed.
let receipts = $derived(applyClientFilters(allReceipts));

// #{#dup1b} #{#dup2b} Detect duplicates on filtered receipts
let duplicateGroups = $derived(detectDuplicates(receipts));

// #{#dup5a} Detect duplicates on ALL receipts for badge count
let allDuplicateGroups = $derived(detectDuplicates(allReceipts));
let duplicateReceiptCount = $derived(
	Array.from(allDuplicateGroups.values()).reduce((sum, ids) => sum + ids.length, 0)
);

let hasActiveFilters = $derived(
	urlDateFrom ||
		urlDateTo ||
		filterMerchant ||
		filterAmountMin ||
		filterAmountMax ||
		filterNeedsReview ||
		filterDuplicates
);

// #{#blk4b} Clear selection
function clearSelection(): void {
	receiptSelection = emptySelection();
}

// #{#blk2a} #{#blk2b} #{#blk3a} #{#blk3b} Selection-based bulk delete
// (native confirm + optimistic update with rollback).
async function deleteSelected(): Promise<void> {
	const idsToDelete = Array.from(receiptSelection.selected);
	if (idsToDelete.length === 0) return;
	if (
		!confirm(
			`Delete ${idsToDelete.length} selected receipt${idsToDelete.length === 1 ? '' : 's'}? This removes the record and the stored file.`
		)
	) {
		return;
	}

	isDeleting = true;
	errorMessage = null;
	successMessage = null;

	// #{#blk3b} Optimistic UI update
	const originalReceipts = [...allReceipts];
	allReceipts = allReceipts.filter((r) => !receiptSelection.selected.has(r.id));

	try {
		// #{#blk3a} Call bulk delete service
		await receiptService.bulkDeleteReceipts(idsToDelete);

		// #{#blk6b} Success feedback
		successMessage = `Successfully deleted ${idsToDelete.length} receipt${idsToDelete.length === 1 ? '' : 's'}`;
		clearSelection();
		setTimeout(() => {
			successMessage = null;
		}, 4000);
	} catch (e: unknown) {
		// #{#blk3b} Rollback on failure
		allReceipts = originalReceipts;
		errorMessage =
			e instanceof Error ? e.message : 'Failed to delete receipts. Please try again.';
		setTimeout(() => {
			errorMessage = null;
		}, 8000);
	} finally {
		isDeleting = false;

