{#snippet amountCell(r: ReceiptRow)}
	{@const dupInfo = getDuplicateInfo(r.id, duplicateGroups)}
	<div class="flex items-center justify-end gap-2">
		{#if r.total_amount == null}
			<!-- Amount OCR could not read: flag rather than show a misleading 0.00 -->
			<span
				class="inline-flex items-center gap-1 rounded bg-yellow-200 px-2 py-0.5 text-xs font-medium text-yellow-800"
				title="Receipt amount could not be read — open the receipt to enter it"
				aria-label="Amount not read"
			>
				⚠ Amount not read
			</span>
		{:else}
			<span
				>{formatCurrencyWithEstimate(
					r.total_amount,
					r.currency,
					r.exchange_rate_to_cad ? r.total_amount * r.exchange_rate_to_cad : null
				)}</span
			>
		{/if}
		{#if dupInfo.isDuplicate}
			<span
				class="inline-flex items-center gap-1 rounded bg-yellow-200 px-2 py-0.5 text-xs font-medium text-yellow-800"
				title="Potential duplicate: {dupInfo.count} receipts with same amount and date"
				aria-label="{dupInfo.count} duplicates"
			>
				<svg
					class="h-3 w-3"
					fill="none"
					stroke="currentColor"
					viewBox="0 0 24 24"
					aria-hidden="true"
				>
