					: 's'} have been verified.
			</p>
			<button
				type="button"
				onclick={() => (filterNeedsReview = false)}
				class="mt-2 rounded border border-gray-300 px-4 py-2 text-sm text-gray-700 hover:bg-gray-50"
			>
				Clear filter
			</button>
		</div>
	{:else}
		<!-- #{#ems1b} Filtered data empty state -->
		<FilteredEmptyState
			count={allReceipts.length}
			itemNoun="receipt"
			onClear={clearClientFilters}
		/>
	{/if}
