<DataTable
	rows={receipts}
	columns={[
		{ key: 'image', header: 'Image', cell: imageCell },
		{ key: 'date', header: 'Date', sortValue: (r) => r.transaction_date ?? '', cell: dateCell },
		{
			key: 'merchant',
			header: 'Merchant',
			sortValue: (r) => r.merchant_name ?? '',
			cell: merchantCell
		},
		{
			key: 'amount',
			header: 'Amount',
			align: 'right',
			sortValue: (r) => r.total_amount ?? 0,
			cell: amountCell
		},
		{ key: 'actions', header: 'Actions', align: 'center', interactive: true, cell: actionsCell }
	]}
	getRowId={(r) => r.id}
	selectable
	bind:selection={receiptSelection}
	onRowClick={openEditModal}
	initialSort={{ key: 'date', direction: 'desc' }}
	rowClass={(r) =>
		receiptSelection.selected.has(r.id)
			? 'border-l-4 border-l-blue-500 bg-blue-50'
			: getDuplicateInfo(r.id, duplicateGroups).isDuplicate
				? 'border-l-4 border-l-yellow-400 bg-yellow-50'
				: ''}
	empty={receiptsEmpty}
/>

<!-- #{#rct6a} #{#rmc2a} Receipt Edit Modal Component - shared across tabs -->
{#if editingReceipt}
	<ReceiptEditModal
		receipt={editingReceipt}
		show={showEditModal}
		isSaving={isSavingReceipt}
		error={editModalError}
		currentCategory={categoryMap[editingReceipt.id] ?? null}
		{categories}
		familyId={familyId ?? undefined}
		onclose={closeEditModal}
		onsave={handleSaveReceipt}
		onCategoryChange={handleCategoryChange}
	/>
{/if}

