async update(id: string, patch: ReceiptInsert) {
	return withRetry(async () => {
		// Strip non-editable fields (id, user_id, created_at, etc.) to prevent
		// Supabase 400 errors from invalid values being sent in the update.
		const safePatch: ReceiptInsert = {};
		const source = patch as Record<string, unknown>;
		const target = safePatch as Record<string, unknown>;
		for (const key of Object.keys(patch)) {
			if (ReceiptService.#EDITABLE_FIELDS.has(key)) {
				target[key] = source[key];
			}
		}

		// #{#dtv1b} #{#dtv2d} Saving a receipt through the edit modal clears the
		// suspicious-date flag. The modal always sends transaction_date, so a save
		// (date corrected or left as-is) is treated as the user's review/confirmation
		// of the date — there is no separate "confirm date" action. Only OCR/automated
		// extraction sets the flag in the first place.
		if ('transaction_date' in safePatch) {
			safePatch.suspicious_date = false;
		}

		const { data, error } = await this.supabase
			.from('receipts')
			.update(safePatch)
			.eq('id', id)
			.select('*')
			.single();
		if (error) throw error;
		return data as ReceiptRow;
	});
}

async createManual(
	values: Required<Pick<ReceiptInsert, 'merchant_name' | 'total_amount' | 'transaction_date'>> &
		Partial<ReceiptInsert>
) {
	return withRetry(async () => {
		// Manual receipts are intentional - user is explicitly entering the date
		// Skip suspicious date validation to avoid false positives for old receipts
		const valuesWithFlag: ReceiptInsert = {
			...values,
			suspicious_date: false
		};

		const { data, error } = await this.supabase
			.from('receipts')
			.insert(valuesWithFlag)
			.select('*')
			.single();
		if (error) throw error;
		return data as ReceiptRow;
	});
}

