function applyFilters(rows: ReconciliationDisplayRow[]): ReconciliationDisplayRow[] {
	return rows.filter((row) => {
		// #{#sdf1b} Filter by date range using URL parameters
		if (!matchesDateRange(row.date, urlDateFrom, urlDateTo)) return false;

		// #{#umf1a} Hide matched rows (show only unmatched receipts and transactions)
		if (hideMatched && row.type === 'matched') {
			return false;
