		// Filter by name (vendor/merchant) - local state
		if (filterName) {
			const nameSearch = filterName.toLowerCase();
			const vendor = row.vendor?.toLowerCase() || '';
			if (!vendor.includes(nameSearch)) return false;
		}

		// Filter by amount range - local state
		if (filterAmountMin && row.amount !== null) {
			const minAmount = parseFloat(filterAmountMin);
			if (!isNaN(minAmount) && Math.abs(row.amount) < minAmount) return false;
		}
		if (filterAmountMax && row.amount !== null) {
			const maxAmount = parseFloat(filterAmountMax);
			if (!isNaN(maxAmount) && Math.abs(row.amount) > maxAmount) return false;
