// #{#spl3a} #{#spl3b} Compute split group info for display
function getSplitGroupInfo(
	receipt: ReceiptRow,
	allRows: ReconciliationDisplayRow[]
): { index: number; total: number; groupAmounts: number[] } | null {
	const groupId = receipt.split_group_id;
	if (!groupId) return null;

	// Find all receipts in this split group from all display rows
	const groupReceipts: ReceiptRow[] = [];
	for (const row of allRows) {
		if (row.receipt?.split_group_id === groupId) {
			groupReceipts.push(row.receipt);
		}
	}

	if (groupReceipts.length <= 1) return null;

	// Sort by created_at for consistent ordering
	groupReceipts.sort((a, b) => a.created_at.localeCompare(b.created_at));
	const index = groupReceipts.findIndex((r) => r.id === receipt.id);

	return {
		index: index + 1,
		total: groupReceipts.length,
		groupAmounts: groupReceipts.map((r) => r.total_amount ?? 0)
	};
}

function openManualReceiptForm(transactionId: string) {
	selectedUnmatchedTransaction = transactionId;
	creatingManualReceipt = true;

